window.kbPageData["views/entry/k-a6e5899721ce1933"] = {"key":"entry/k-a6e5899721ce1933","state":{"route":"entry/k-a6e5899721ce1933"},"node":{"id":"k-a6e5899721ce1933","mode":"k","title":"公务员参与营利性活动的限制","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["公务员出资设立有限责任公司属于参与营利性活动"],"qs":["江苏 2024 B类 行测#10"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"公务员不得违反有关规定从事或者参与营利性活动。以股东身份出资设立有限责任公司，属于本题所指的参与营利性活动。","review":{"definition":"公务员不得违反有关规定从事或者参与营利性活动。以股东身份出资设立有限责任公司，属于本题所指的参与营利性活动。","explanation":"有限责任公司属于营利法人，熊某作为小股东出资参与设立，持股比例小也改变不了行为性质，因此选D。C项中的张某因继承取得股权，随后转让该股权，题中将其认定为处分依法继承的财产。","references":[],"evidence":"熊某作为小股东出资设立有限责任公司属于从事营利性活动。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 B类 行测#10":{"paper":"江苏 2024 B类 行测","n":10,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",2],"asrc":["8dd171daee6fc74e9718.pdf",4],"card":"24e2d5832ef43160771f7921","links":[{"id":"k-a6e5899721ce1933","role":"直接考查","why":"有限责任公司属于营利法人，作为小股东参与设立也适用公务员的营利活动禁令。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-a6e5899721ce1933":[["江苏 2024 B类 行测#10"]]}};
